argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class Win32Gemini {
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
 [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd,int n);
 [DllImport("user32.dll")] public static extern bool SetCursorPos(int X,int Y);
 [DllImport("user32.dll")] public static extern void mouse_event(uint f,uint dx,uint dy,uint data,UIntPtr extra);
}
"@
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'No visible Edge window'}
[Win32Gemini]::ShowWindow($edge.MainWindowHandle,9)|Out-Null
[Win32Gemini]::SetForegroundWindow($edge.MainWindowHandle)|Out-Null
Start-Sleep -Milliseconds 500
[System.Windows.Forms.SendKeys]::SendWait('^l')
[System.Windows.Forms.SendKeys]::SendWait('https://gemini.google.com/app')
[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
Start-Sleep -Seconds 7
[Win32Gemini]::SetCursorPos(600,600)|Out-Null
[Win32Gemini]::mouse_event(2,0,0,0,[UIntPtr]::Zero)
[Win32Gemini]::mouse_event(4,0,0,0,[UIntPtr]::Zero)
Start-Sleep -Milliseconds 400
[System.Windows.Forms.SendKeys]::SendWait('^a')
[System.Windows.Forms.SendKeys]::SendWait('^c')
Start-Sleep -Milliseconds 300
$clip=[string](Get-Clipboard -Raw -ErrorAction SilentlyContinue)
if($clip.Length -gt 12000){$clip=$clip.Substring(0,12000)}
[System.Windows.Forms.SendKeys]::SendWait('{ESC}')
$focus=@()
for($i=0;$i -lt 28;$i++){
 [System.Windows.Forms.SendKeys]::SendWait('{TAB}')
 Start-Sleep -Milliseconds 80
 $e=[System.Windows.Automation.AutomationElement]::FocusedElement
 if($null -ne $e){
   $r=$e.Current.BoundingRectangle
   $focus += [pscustomobject]@{i=$i;type=$e.Current.ControlType.ProgrammaticName;name=[string]$e.Current.Name;aid=[string]$e.Current.AutomationId;x=[int]$r.X;y=[int]$r.Y;w=[int]$r.Width;h=[int]$r.Height}
 }
}
[pscustomobject]@{title=$edge.MainWindowTitle;clipboard=$clip;focus=$focus} | ConvertTo-Json -Depth 6 -Compress
